#include <stdio.h>

int fib(int n) {
    int a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        int next = a + b;
        a = b;
        b = next;
    }
    return a;
}

int main() {
    for (int i = 0; i < 8; i++) {
        printf("%d ", fib(i));
    }
    printf("\n");
    return 0;
}
